export type Cell = [number, number];

const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  x === otherX && y === otherY;

const isNeighborOf = (cell: Cell, candidate: Cell): boolean => {
  const [x, y] = cell;
  const [candidateX, candidateY] = candidate;

  return (
    Math.abs(candidateX - x) <= 1 &&
    Math.abs(candidateY - y) <= 1 &&
    !isSameCell(cell, candidate)
  );
};

const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((candidate) => isNeighborOf(cell, candidate)).length;

const survives = (liveNeighbors: number): boolean =>
  liveNeighbors === 2 || liveNeighbors === 3;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) =>
    survives(countLiveNeighbors(cell, liveCells)),
  );
}

